def allocate_tax_cents(lines: list[int], total_tax: int) -> list[int]:
    s = sum(lines)
    if s <= 0:
        return [0] * len(lines)
    raw = [(x * total_tax) / s if x > 0 else 0.0 for x in lines]
    floors = [int(v) for v in raw]
    rem = total_tax - sum(floors)
    order = sorted(
        [i for i, x in enumerate(lines) if x > 0],
        key=lambda i: (raw[i] - floors[i], lines[i]),
        reverse=True,
    )
    for idx in order[:rem]:
        floors[idx] += 1
    return floors

