class TaskScheduler:
    def __init__(self) -> None:
        self._pending: list[tuple[int, int, str, set[str]]] = []
        self._done: set[str] = set()
        self._seq = 0

    def add_job(self, job_id: str, priority: int, deps: list[str] | None = None) -> None:
        self._pending.append((-priority, self._seq, job_id, set(deps or [])))
        self._seq += 1

    def mark_done(self, job_id: str) -> None:
        self._done.add(job_id)

    def pop_ready(self) -> str | None:
        ready = [item for item in self._pending if item[3].issubset(self._done)]
        if not ready:
            return None
        best = min(ready, key=lambda x: (x[0], x[1]))
        self._pending.remove(best)
        return best[2]

