import posixpath
from urllib.parse import parse_qsl, urlencode, urlparse, urlunparse

def normalize_request_url(url: str) -> str:
    parsed = urlparse(url.strip())
    scheme = parsed.scheme.lower()
    host = (parsed.hostname or '').lower()
    port = parsed.port
    if (scheme == 'http' and port == 80) or (scheme == 'https' and port == 443):
        port = None
    netloc = f'{host}:{port}' if port is not None else host
    parts = [p for p in parsed.path.split('/') if p and p != '.']
    stack: list[str] = []
    for seg in parts:
        if seg == '..':
            if not stack:
                raise ValueError('path traversal above root')
            stack.pop()
        else:
            stack.append(seg)
    norm_path = '/' + posixpath.join(*stack) if stack else '/'
    q = urlencode(sorted(parse_qsl(parsed.query, keep_blank_values=True)))
    return urlunparse((scheme, netloc, norm_path, '', q, ''))

