import math

class RollingWindowStats:
    def __init__(self, window_sec: float) -> None:
        self.window_sec = window_sec
        self._events: list[tuple[float, float]] = []

    def record(self, ts: float, value: float) -> None:
        self._events.append((ts, value))

    def summary(self, now: float) -> dict[str, float]:
        cutoff = now - self.window_sec
        self._events = [(t, v) for t, v in self._events if t >= cutoff]
        if not self._events:
            return {'count': 0.0, 'mean': 0.0, 'p95': 0.0}
        vals = sorted(v for _, v in self._events)
        mean = sum(vals) / len(vals)
        idx = max(0, min(len(vals) - 1, math.ceil(0.95 * len(vals)) - 1))
        return {'count': float(len(vals)), 'mean': mean, 'p95': vals[idx]}

