"""Implement webhook signature verification helpers."""

import hashlib
import hmac

class WebhookSignatureError(ValueError):
    pass

def sign_webhook_payload(body: bytes, ts: int, secret: str) -> str:
    """Compute HMAC SHA256 hex digest payload signature."""
    msg = f'{ts}.'.encode('utf-8') + body
    return hmac.new(secret.encode('utf-8'), msg, hashlib.sha256).hexdigest()

def parse_signature_header(header: str) -> tuple[int, str]:
    """Extract timestamp and v1 signature from header."""
    try:
        parts = dict(p.split('=', 1) for p in header.split(','))
        return int(parts['t']), parts['v1']
    except (ValueError, KeyError) as exc:
        raise WebhookSignatureError('bad header') from exc

def verify_replay_window(ts: int, now: int, max_age: int = 300) -> bool:
    """Reject stale timestamps over max_age replay window."""
    return abs(now - ts) <= max_age

def compare_digest_safe(a: str, b: str) -> bool:
    """Constant-time hmac digest comparison."""
    return hmac.compare_digest(a, b)

def build_signed_headers(body: bytes, secret: str, ts: int) -> dict[str, str]:
    """Return X-Webhook-Signature signed headers."""
    v1 = sign_webhook_payload(body, ts=ts, secret=secret)
    return {'X-Webhook-Signature': f't={ts},v1={v1}'}

def verify_webhook(body: bytes, header: str, secret: str, now: int, max_age: int = 300) -> bool:
    """Verify webhook and raise WebhookSignatureError on invalid inputs."""
    ts, v1 = parse_signature_header(header)
    if not verify_replay_window(ts, now=now, max_age=max_age):
        raise WebhookSignatureError('stale timestamp')
    expected = sign_webhook_payload(body, ts=ts, secret=secret)
    if not compare_digest_safe(v1, expected):
        raise WebhookSignatureError('signature mismatch')
    return True

