"""Implement HTTP retry engine policy."""

IDEMPOTENT_VERBS = {'GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS'}

def classify_status_code(status: int) -> bool:
    """Return True for 429 and 5xx status codes."""
    return status == 429 or 500 <= status < 600

def parse_retry_after(header_val: str | None) -> int | None:
    """Parse integer seconds header or return None."""
    if header_val is not None and header_val.strip().isdigit():
        return int(header_val.strip())
    return None

def compute_backoff_ms(attempt: int, base_ms: int = 100, cap_ms: int = 5000) -> int:
    """Apply capped exponential backoff growth in ms."""
    return min(cap_ms, base_ms * (2 ** max(0, attempt)))

def should_retry_method(method: str) -> bool:
    """Restrict retries to idempotent HTTP verbs."""
    return method.upper() in IDEMPOTENT_VERBS

def track_retry_budget(spent_ms: int, next_ms: int, max_total_delay_ms: int = 10000) -> bool:
    """Enforce max_total_delay_ms retry budget limit."""
    return spent_ms + next_ms <= max_total_delay_ms

def decide_next_retry(
    method: str,
    status: int,
    attempt: int,
    spent_ms: int,
    retry_after: str | None = None,
    max_total_delay_ms: int = 10000,
) -> int | None:
    """Return wait_ms when next retry is allowed."""
    if not should_retry_method(method) or not classify_status_code(status):
        return None
    ra = parse_retry_after(retry_after)
    wait_ms = ra * 1000 if ra is not None else compute_backoff_ms(attempt)
    if not track_retry_budget(spent_ms, wait_ms, max_total_delay_ms):
        return None
    return wait_ms

