"""Opaque cursor pagination helpers."""

import base64
import hashlib
import json

def _checksum(offset: int, sort_key: str) -> str:
    return hashlib.sha256(f'{offset}:{sort_key}'.encode()).hexdigest()[:8]

def encode_cursor(offset: int, sort_key: str) -> str:
    """Serialize offset and sort_key via base64."""
    payload = {
        'offset': offset,
        'sort_key': sort_key,
        'sig': _checksum(offset, sort_key),
    }
    raw = json.dumps(payload, separators=(',', ':')).encode('utf-8')
    return base64.urlsafe_b64encode(raw).decode('ascii')

def decode_cursor(token: str) -> tuple[int, str]:
    """Validate payload checksum and return fields."""
    try:
        b = base64.urlsafe_b64decode(token.encode('ascii'))
        raw = b.decode('utf-8')
        data = json.loads(raw)
        offset = int(data['offset'])
        sort_key = str(data['sort_key'])
        if data.get('sig') != _checksum(offset, sort_key):
            raise ValueError('cursor checksum mismatch')
        return offset, sort_key
    except Exception as exc:
        raise ValueError('invalid cursor') from exc

def clamp_page_size(limit: int, max_limit: int = 100) -> int:
    """Bound requested limit between 1 and max_limit."""
    return max(1, min(max_limit, limit))

def slice_page(
    items: list[str],
    offset: int,
    limit: int,
    sort_key: str = 'id',
) -> tuple[list[str], str | None]:
    """Return items slice and next_cursor token."""
    end = offset + limit
    chunk = items[offset:end]
    nxt = encode_cursor(end, sort_key) if end < len(items) else None
    return chunk, nxt

def build_page_envelope(items: list[str], cursor: str | None, limit: int) -> dict[str, object]:
    """Return items, next_cursor, and has_more envelope."""
    offset, sort_key = decode_cursor(cursor) if cursor else (0, 'id')
    safe_limit = clamp_page_size(limit)
    chunk, nxt = slice_page(items, offset, safe_limit, sort_key=sort_key)
    return {'items': chunk, 'next_cursor': nxt, 'has_more': nxt is not None}

