"""Deterministic feature flag evaluation helpers."""

import hashlib

def hash_bucket(flag_name: str, user_id: str) -> int:
    """Compute stable percentage bucket 0 to 99."""
    d = hashlib.sha256(f'{flag_name}:{user_id}'.encode()).hexdigest()
    return int(d[:8], 16) % 100

def match_explicit_allowlist(user_id: str, allow: set[str]) -> bool:
    """Check user_id explicit allowlist override rules."""
    return user_id in allow

def match_denylist(user_id: str, deny: set[str]) -> bool:
    """Ensure excluded users in denylist receive False."""
    return user_id in deny

def check_rollout_percent(flag_name: str, user_id: str, pct: int) -> bool:
    """Evaluate user hash_bucket below pct."""
    return hash_bucket(flag_name, user_id) < pct

def evaluate_attribute_rules(rules: dict[str, str], ctx: dict[str, str]) -> bool:
    """Match tenant and plan attribute filters."""
    if not rules:
        return False
    return all(ctx.get(k) == v for k, v in rules.items())

def describe_decision(flag: dict[str, object], ctx: dict[str, str]) -> str:
    """Return matched rule reason string."""
    uid = ctx.get('user_id', '')
    deny = set(flag.get('deny', []))  # type: ignore[arg-type]
    allow = set(flag.get('allow', []))  # type: ignore[arg-type]
    attrs = dict(flag.get('attrs', {}))  # type: ignore[arg-type]
    pct = int(flag.get('percent', 0))  # type: ignore[arg-type]
    name = str(flag.get('name', ''))
    if match_denylist(uid, deny):
        return 'denylist'
    if match_explicit_allowlist(uid, allow):
        return 'allowlist'
    if evaluate_attribute_rules(attrs, ctx):
        return 'attributes'
    if check_rollout_percent(name, uid, pct):
        return 'rollout'
    return 'off'

def is_feature_enabled(flag: dict[str, object], ctx: dict[str, str]) -> bool:
    """Combine deny, allow, attributes, and pct rules."""
    return describe_decision(flag, ctx) in {
        'allowlist',
        'attributes',
        'rollout',
    }

