    return a + b

def split_even_cents(total: int, ways: int) -> list[int]:
    if ways <= 0:
        raise ValueError('ways must be positive')
    base, rem = divmod(total, ways)
    return [base + (1 if i < rem else 0) for i in range(ways)]

