def format_bytes(num: int) -> str:
    if num < 1024:
        return f'{num} B'
    val = float(num)
    for unit in ('KiB', 'MiB', 'GiB', 'TiB'):
        val /= 1024.0
        if val < 1024.0 or unit == 'TiB':
            return f'{val:.1f} {unit}'
    return f'{num} B'
